let currentLanguage: Language =
  (["es", "en", "fr"] as Language[]).includes(localStorage.getItem(STORAGE_KEY) as Language)
    ? (localStorage.getItem(STORAGE_KEY) as Language)
    : "es";
document.documentElement.lang = currentLanguage;

export function getLanguage(): Language {
  return currentLanguage;
}

export function setLanguage(language: Language): void {
  currentLanguage = language;
  localStorage.setItem(STORAGE_KEY, language);
  document.documentElement.lang = language;
  window.dispatchEvent(new CustomEvent("languagechange", { detail: language }));
}

export function t(text: string): string {
  const exact = currentLanguage === "en"
    ? translations[text] ?? englishExtra[text]
    : currentLanguage === "fr"
      ? frenchTranslations[text] ?? frenchExtra[text]
      : spanishFromEnglish[text];
  if (exact !== undefined) return exact;

  let result = text;
  const fragments = currentLanguage === "es"
    ? spanishFromEnglish
    : currentLanguage === "fr"
      ? { ...translations, ...englishExtra, ...frenchTranslations, ...frenchExtra }
      : { ...translations, ...englishExtra };
  for (const [source, translated] of Object.entries(fragments).sort((a, b) => b[0].length - a[0].length)) {
    if (source.length > 5 && result.includes(source)) result = result.split(source).join(translated);
  }
  return result;
}

export function languageLabel(): string {
  return currentLanguage.toUpperCase();
}

export function languageName(language: Language): string {
  return { es: "Español", en: "English", fr: "Français" }[language];
}
